/* Student history workshop: linked chronologies and evidence-based challenges. */
(() => {
'use strict';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let tracks=[],trackId='huellas',mode='explore',index=0,level='explorar',order=[],locked=false,answered=false,round=0,score=0,notes={};
const track=()=>tracks.find(t=>t.id===trackId);
const levels={explorar:['Explorar','Cuenta lo que cambió con tus palabras o mediante un dibujo.'],comprender:['Comprender','Relaciona un cambio con una causa y una consecuencia. Usa una evidencia.'],profundizar:['Profundizar','Contrasta dos fuentes: autoría, contexto, propósito y límites. Explica qué voces faltan.']};
function setRound(){order=track().events.map((c,i)=>i).reverse();locked=false;answered=false;round=0;score=0;}
function source(c){return `<a href="${esc(c.source[1])}" target="_blank" rel="noopener">${esc(c.source[0])}</a>`;}
function render(){
 const t=track(),host=$('#historyWorkshopApp');if(!t||!host)return;
 host.innerHTML=`<div class="hw-controls"><label>Recorrido<select id="hwTrack">${tracks.map(x=>`<option value="${x.id}" ${x.id===trackId?'selected':''}>${esc(x.title)}</option>`).join('')}</select></label><label>Profundidad<select id="hwLevel">${Object.entries(levels).map(([id,l])=>`<option value="${id}" ${id===level?'selected':''}>${l[0]}</option>`).join('')}</select></label><button id="hwProject" class="atlas-outline">Proyectar</button></div><nav class="hw-modes" aria-label="Actividades de historia">${[['explore','Explorar el tiempo'],['order','Ordenar el pasado'],['connect','Conectar cambios'],['evidence','Investigar una pregunta']].map(([id,l])=>`<button data-hw-mode="${id}" aria-pressed="${id===mode}">${l}</button>`).join('')}</nav><div class="hw-layout"><div class="hw-main">${mode==='explore'?explore(t):mode==='order'?puzzle(t):challenge(t)}</div><aside class="hw-notebook"><p class="eyebrow">MI CUADERNO DE HISTORIA</p><h2>${esc(t.question)}</h2><p>${esc(levels[level][1])}</p><label for="hwNote">Mi explicación y la evidencia que la apoya</label><textarea id="hwNote" rows="6" placeholder="Pienso que… Mi evidencia es… Todavía me pregunto…">${esc(notes[trackId]||'')}</textarea><p class="hw-local">La respuesta se conserva mientras esta página permanezca abierta. Puedes imprimirla.</p><button id="hwPrint" class="atlas-outline">Imprimir mi trabajo</button><details><summary>Una sesión de 30 minutos</summary><ol><li>5 min: observa la imagen y plantea una pregunta.</li><li>10 min: explora los seis hitos y una fuente.</li><li>10 min: resuelve un reto en pareja y explica tu decisión.</li><li>5 min: revisa tu explicación inicial.</li></ol><p>Se aceptan respuestas orales, dibujos o textos. Valora la justificación y la revisión de ideas.</p></details></aside></div>`;
 bind();
}
function explore(t){const c=t.events[index];return `<figure class="hw-art"><img src="${t.image}" alt="${esc(t.alt)}" width="1536" height="1024"><figcaption>Recreación conceptual con IA. Las personas son anónimas; la escena no documenta ninguno de los hitos.</figcaption></figure><h2>${esc(t.title)}</h2><p>${esc(t.lens)}</p><p class="hw-scale">Secuencia cronológica con separación uniforme: los espacios no representan la duración entre fechas. Las fechas aproximadas mantienen su contexto.</p><ol class="hw-timeline" aria-label="Hitos del recorrido">${t.events.map((x,i)=>`<li><button data-hw-event="${i}" aria-pressed="${i===index}"><span>${esc(x.date)}</span><strong>${esc(x.title)}</strong></button></li>`).join('')}</ol><article class="hw-detail" aria-live="polite"><p class="eyebrow">HITO ${index+1} DE ${t.events.length} · ${esc(c.region)}</p><h3>${esc(c.title)}</h3><p>${esc(c.text)}</p><div class="hw-connections"><div><strong>Antecedente</strong><p>${esc(c.cause)}</p></div><div><strong>Consecuencia</strong><p>${esc(c.effect)}</p></div></div><details><summary>Investiga y profundiza</summary><p>${esc(c.question)}</p><p>${esc(c.activity)}</p>${level==='profundizar'?'<p>¿Quién produjo la fuente? ¿Cuándo y con qué propósito? Distingue documento histórico de explicación institucional actual. Ninguna fuente representa todas las experiencias.</p>':''}</details><p class="hw-source">Fuente de la explicación: ${source(c)} · Revisión: 8 de octubre de 2026.</p>${c.route?`<a class="atlas-outline" href="#historietas/${c.route}/${Number(c.id.split('-').pop())}">Abrir episodio ilustrado</a>`:''}</article>`;}
function puzzle(t){return `<h2>Ordenar el pasado</h2><p>Mueve las tarjetas con los botones hasta ordenarlas de la más antigua a la más reciente. Después, explica una relación entre dos hitos.</p><ol class="hw-sort">${order.map((n,i)=>`<li><span class="hw-number">${i+1}</span><div><strong>${esc(t.events[n].title)}</strong>${locked?`<p>${esc(t.events[n].date)}</p>`:''}</div><div class="hw-move"><button data-hw-up="${i}" ${i===0||locked?'disabled':''} aria-label="Subir ${esc(t.events[n].title)}">Subir</button><button data-hw-down="${i}" ${i===order.length-1||locked?'disabled':''} aria-label="Bajar ${esc(t.events[n].title)}">Bajar</button></div></li>`).join('')}</ol><p id="hwFeedback" role="status">${locked?'Orden resuelto. ¿Qué ocurrió antes y qué cambió después?':''}</p><div class="hw-actions"><button id="hwCheck" class="atlas-button" ${locked?'disabled':''}>Comprobar orden</button><button id="hwHint" class="atlas-outline" ${locked?'disabled':''}>Pedir una pista</button><button id="hwReset" class="atlas-outline">Volver a intentar</button></div>`;}
function options(t,c){let opts=mode==='connect'?[c.effect,...t.events.filter(x=>x.id!==c.id).slice(0,2).map(x=>x.effect)]:[c.answer,...c.distractors];const shift=round%3;return opts.map((text,i)=>({text,correct:i===0})).slice(shift).concat(opts.map((text,i)=>({text,correct:i===0})).slice(0,shift));}
function challenge(t){if(round>=t.events.length)return `<div class="hw-result"><p class="eyebrow">RECORRIDO COMPLETADO</p><h2>${score} de ${t.events.length} respuestas acertadas</h2><p>El resultado es un punto de partida. Escribe una idea que revisaste y qué evidencia te ayudó.</p><button id="hwReplay" class="atlas-button">Repetir el recorrido</button></div>`;const c=t.events[round];return `<p class="eyebrow">RETO ${round+1} DE ${t.events.length}</p><h2>${mode==='connect'?'¿Qué consecuencia se relaciona con este hito?':esc(c.question)}</h2><p class="hw-stimulus">${mode==='connect'?esc(c.title)+' · '+esc(c.date)+'<br>'+esc(c.cause):esc(c.title)+' · '+esc(c.date)}</p><div class="hw-answers">${options(t,c).map((o,i)=>`<button data-hw-answer="${i}">${esc(o.text)}</button>`).join('')}</div><div id="hwFeedback" role="status"></div><button id="hwNext" class="atlas-button" disabled>Siguiente pregunta</button><details><summary>Consultar antes de decidir</summary><p>${esc(c.text)}</p>${source(c)}</details>`;}
function bind(){
 $('#hwTrack').onchange=e=>{trackId=e.target.value;index=0;setRound();render();};$('#hwLevel').onchange=e=>{level=e.target.value;render();};
 $$('[data-hw-mode]').forEach(b=>b.onclick=()=>{mode=b.dataset.hwMode;setRound();render();});
 $$('[data-hw-event]').forEach(b=>b.onclick=()=>{index=Number(b.dataset.hwEvent);render();});
 $('#hwNote').oninput=e=>notes[trackId]=e.target.value;$('#hwPrint').onclick=()=>window.print();$('#hwProject').onclick=()=>$('#projectorBtn').click();
 const move=(i,j)=>{[order[i],order[j]]=[order[j],order[i]];render();};
 $$('[data-hw-up]').forEach(b=>b.onclick=()=>{const i=+b.dataset.hwUp;if(!locked&&i>0)move(i,i-1);});
 $$('[data-hw-down]').forEach(b=>b.onclick=()=>{const i=+b.dataset.hwDown;if(!locked&&i<order.length-1)move(i,i+1);});
 if($('#hwCheck'))$('#hwCheck').onclick=()=>{if(locked)return;const good=order.every((n,i)=>i===n);if(good){locked=true;render();}else $('#hwFeedback').textContent='Todavía hay una inversión. Compara qué cambió antes y después; puedes pedir una pista.';};
 if($('#hwHint'))$('#hwHint').onclick=()=>$('#hwFeedback').textContent=`El primer hito es «${track().events[0].title}» (${track().events[0].date}). Busca su lugar.`;
 if($('#hwReset'))$('#hwReset').onclick=()=>{setRound();render();};
 $$('[data-hw-answer]').forEach(b=>b.onclick=()=>{if(answered)return;answered=true;const c=track().events[round],opts=options(track(),c),right=opts[+b.dataset.hwAnswer].correct;if(right)score++;$$('[data-hw-answer]').forEach((x,i)=>{x.disabled=true;if(opts[i].correct)x.classList.add('hw-correct');});$('#hwFeedback').innerHTML=`<strong>${right?'La evidencia apoya tu respuesta.':'Revisemos la relación.'}</strong><p>${esc(mode==='connect'?c.text:c.answer)}</p><p>${source(c)}</p><p>Explica qué dato sostiene esta respuesta y qué no puedes concluir todavía.</p>`;$('#hwNext').disabled=false;});
 if($('#hwNext'))$('#hwNext').onclick=()=>{if(!answered)return;round++;answered=false;render();};
 if($('#hwReplay'))$('#hwReplay').onclick=()=>{setRound();render();};
}
async function init(){try{const r=await fetch('data/history-workshop.json');if(!r.ok)throw Error('history');const data=await r.json();tracks=data.tracks;level=localStorage.getItem('atlas-audience')||'explorar';if(!levels[level])level='explorar';setRound();render();}catch(e){$('#historyWorkshopApp').innerHTML='<p>No se pudo cargar el taller.</p><button id="hwRetry" class="atlas-button">Reintentar</button>';$('#hwRetry').onclick=init;}}
window.addEventListener('hashchange',()=>{if(location.hash==='#taller-historia'&&tracks.length)render();});
window.AtlasHistoryWorkshop={init};init();
})();
